content.query:
let Reporting = toscalar(Heartbeat | summarize dcount(Computer));
let Privileged = toscalar(union (Syslog | where Facility in ('auth', 'authpriv') and SyslogMessage has 'sudo' | project Computer), (Event | where EventLog == 'Security' and EventID in (4672, 4673, 4674) | project Computer) | count);
let Changes = toscalar(ConfigurationChange | where isnotempty(ConfigChangeType) | count);
let Software = toscalar(ConfigurationChange | where ConfigChangeType == 'Software' | count);
print data = pack_array(
    pack('Order', 1, 'Label', 'Servers reporting', 'Value', Reporting, 'Note', 'sending telemetry'),
    pack('Order', 2, 'Label', 'Privileged events', 'Value', Privileged, 'Note', 'sudo and Windows privilege use'),
    pack('Order', 3, 'Label', 'Config changes', 'Value', Changes, 'Note', 'services, daemons and software'),
    pack('Order', 4, 'Label', 'Software changes', 'Value', Software, 'Note', 'installed, updated or removed'))
| mv-expand data
| extend Order = toint(data.Order)
| order by Order asc
| project Label = tostring(data.Label), Value = tolong(data.Value), Note = tostring(data.Note)
